                BigDecimal.class, currency.name(), Date.valueOf(on)).stream().findFirst().orElseGet(() -> usdPer(currency));
    }

    /** The US dollars one unit of the currency is worth: one for the dollar or a currency with no rate set. */
    public BigDecimal usdPer(Currency currency) {
        if (currency == Currency.USD) {
            return BigDecimal.ONE;
        }
        return jdbc.queryForList("SELECT setting_value FROM app_setting WHERE name = ?", String.class, USD_PER + currency.name())
                .stream().findFirst().map(v -> new BigDecimal(v.trim())).orElse(BigDecimal.ONE);
    }

    /**
     * The amount paid in one currency converted into another through US dollars: amount x (dollars per
     * unit paid) / (dollars per unit of the other), at the rates in force on the date, worked out exactly
     * and rounded down to the other's step, so the client is never credited more than was received.
     */
    public BigDecimal convert(BigDecimal amount, Currency from, Currency to, LocalDate on) {
        if (from == to) {
            return amount.setScale(to.scale());
        }
        return to.divideDownToStep(amount.multiply(usdPer(from, on)), usdPer(to, on));
    }
}
package net.officefloor.hq.app.clients;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/**
 * A currency a client is billed in, with the symbol its amounts are shown with and how many decimals
 * they have: yen have none, so every amount for a yen client is in whole yen.
 */
public enum Currency {
    USD("$", 2), EUR("€", 2), GBP("£", 2), JPY("¥", 0), CHF("CHF ", 2);

    private final String symbol;
    private final int scale;

    Currency(String symbol, int scale) {
        this.symbol = symbol;
        this.scale = scale;
    }

    /** How many decimals an amount has: 2 (to the cent), or 0 for yen. */
    public int scale() {
        return scale;
    }

    /** Whether the amount is whole in this currency: no more decimals than {@link #scale()}. */
    public boolean isWhole(BigDecimal amount) {
        return amount.stripTrailingZeros().scale() <= scale;
    }

    /** This currency's step: whole yen, 0.05 for Swiss francs, otherwise the cent. */
    public BigDecimal step() {
        return this == CHF ? new BigDecimal("0.05") : BigDecimal.ONE.movePointLeft(scale);
    }

    /** The smallest coin cash is counted out in: whole yen, otherwise 0.05 (there are no one- or two-cent coins). */
    public BigDecimal cashStep() {
        return this == JPY ? BigDecimal.ONE : new BigDecimal("0.05");
    }

    /** The amount rounded half up to the nearest {@link #cashStep()}: what it comes to in cash. */
    public BigDecimal toCash(BigDecimal amount) {
        BigDecimal step = cashStep();
        return amount.divide(step, 0, RoundingMode.HALF_UP).multiply(step).setScale(scale);
    }

    /** Whether the amount can be counted out in cash: a whole number of {@link #cashStep()}s. */
    public boolean isCash(BigDecimal amount) {
        return amount.remainder(cashStep()).signum() == 0;
    }

    /**
     * The exact quotient amount / divisor rounded down (towards zero) to this currency's step, worked
     * out in decimals in one division so that a quotient landing on a step stays on it.
     */
    public BigDecimal divideDownToStep(BigDecimal amount, BigDecimal divisor) {
        BigDecimal step = step();
        return amount.divide(divisor.multiply(step), 0, RoundingMode.DOWN).multiply(step).setScale(scale);
    }

    /** The amount with its symbol and thousands separators, e.g. €1,234.50 or ¥1,235. */
    public String format(BigDecimal amount) {
        DecimalFormat number = new DecimalFormat(scale == 0 ? "#,##0" : "#,##0.00",
                DecimalFormatSymbols.getInstance(Locale.US));
        BigDecimal rounded = amount.setScale(scale, RoundingMode.HALF_UP);
        return (rounded.signum() < 0 ? "-" : "") + symbol + number.format(rounded.abs());
    }

    /** The currency with the code, or null when there is no such currency. */
    public static Currency of(String code) {
        for (Currency c : values()) {
            if (c.name().equals(code)) {
                return c;
            }
        }
        return null;
    }

    /** The currency with the code; US dollars when there is none. */
    public static Currency orUsd(String code) {
        Currency c = code == null ? null : of(code);
        return c == null ? USD : c;
    }
}
